// Diagram source data. Values are invented solely to demonstrate the supplied text.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { extraDefinitions } from './educationWorkedExamples.mjs'
const content=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../src/content')
export const definitions=[...extraDefinitions]
const c={up:'#34d399',down:'#fb7185',blue:'#38bdf8',gold:'#fbbf24',purple:'#c4b5fd'}
const chart=(bars,extra={})=>({type:'chart',bars,...extra})
const lines=(series,extra={})=>({type:'lines',series,...extra})
const columns=(values,labels,extra={})=>({type:'columns',values,labels,...extra})
const flow=(steps,note)=>({type:'flow',steps,note})
const range=(low,high,current,levels,formula,extra={})=>({type:'range',low,high,current,levels,formula,...extra})
const smooth=(start,end,n=21)=>Array.from({length:n},(_,i)=>start+(end-start)*i/(n-1))
const price=[100,104,102,109,108,113,112,119,117,124,123,130]
const down=[[112,114,105,107,85],[107,109,100,102,95],[102,104,94,96,100]]
const up=[[88,96,86,94,80],[94,102,92,100,95],[100,109,98,107,100]]
const base=[[99,103,96,101,85],[101,104,97,99,90],[99,103,96,100,75],[100,102,97,99,60],[99,102,98,101,45]]
const add=(article,section,id,title,caption,scene,placement='end')=>definitions.push({article,section,id,title,caption,scene,placement})
const comp=(section,id,title,caption,scene,placement='end')=>add('vsaKompendium',section,id,title,caption,scene,placement)
const strip=s=>s.replace(/\*\*/g,'').replace(/\*([^*]+)\*/g,'$1').replace(/`/g,'')
function rules(article,section,prefix,scenes) {
  const all=['en','pl'].map(lang=>fs.readFileSync(path.join(content,`${article}${lang==='en'?'.en':''}.md`),'utf8'))
  const headings=all.map(md=>[...md.matchAll(/^#{2,4} .+$/gm)])
  const sectionIndex=headings[0].findIndex(h=>h[0].trim().replace(/^#+ /,'')===section)
  if(sectionIndex<0) throw new Error(`Missing rule section for ${article}`)
  const tables=all.map((md,lang)=>{
    const start=headings[lang][sectionIndex].index
    const end=headings[lang][sectionIndex+1]?.index??md.length
    return [...md.slice(start,end).matchAll(/^\| (\d+) \| ([^|]+) \| ([^|]+) \|\r?$/gm)]
  })
  if(tables.some(t=>t.length!==scenes.length)) throw new Error(`Missing rules for ${article}`)
  scenes.forEach((scene,i)=>add(article,section,`${prefix}-rule-${i+1}`,tables.map(t=>`${prefix==='pocket-pivot'?'Pocket Pivot':prefix==='volume-breakout'?'Volume Breakout':prefix==='weinstein'?'Weinstein':'Minervini'} ${i+1} — ${strip(t[i][2])}`),tables.map(t=>strip(t[i][3])),scene,'table'))
}

