add('minervini',minSection,'relative-strength-weights',['Relative-strength weighting','Wagi siły względnej'],['A weighted return is ranked against other stocks in the same market; a raw return is not itself a percentile.','Ważona stopa zwrotu jest porównywana z innymi spółkami tego samego rynku; sama stopa zwrotu nie jest percentylem.'],columns([40,20,20,20],[['3 months','3 miesiące'],['6 months','6 miesięcy'],['9 months','9 miesięcy'],['12 months','12 miesięcy']],{unit:['WEIGHT (%)','WAGA (%)'],note:['Weighted return → market rank → rule 8','Ważona stopa zwrotu → ranking rynku → warunek 8']}))
add('minervini','What you see in the app','minervini-score',['Score and first activation','Wynik i pierwsza aktywacja'],['The score is the share of rules met; a chart marker identifies the first day all seven structural rules become true.','Wynik to udział spełnionych reguł; znacznik wskazuje pierwszy dzień spełnienia wszystkich siedmiu reguł strukturalnych.'],flow([['6/7 rules','6/7 reguł'],['7/7: activation','7/7: aktywacja'],['7/7: still active','7/7: nadal aktywny']],['Ranking: 8 rules including relative strength','Ranking: 8 reguł, w tym siła względna']))

