// Course pattern definitions: explicit OHLCV examples, no projected returns.
const coursePatterns=[
  ['1. Bag Holding','bag-holding',['Bag Holding','Bag Holding'],['Narrow range after a decline, a mid-range close and exceptional volume. The example is a Down Bar; body colour alone does not define the pattern.','Wąski zakres po spadku, zamknięcie w środku i wyjątkowy wolumen. Przykład jest Down Barem; sam kolor korpusu nie definiuje formacji.'],chart([...down,[95,97,91,94,350]])],
  ['2. Selling Climax','selling-climax',['Selling Climax','Selling Climax'],['A wide downward range on exceptional volume closes away from the low. A later test is still needed.','Szeroki ruch spadkowy na wyjątkowym wolumenie zamyka się z dala od minimum. Nadal potrzebny jest późniejszy test.'],chart([...down,[96,98,74,86,360]])],
  ['3. Stopping Volume','stopping-volume',['Stopping Volume','Stopping Volume'],['A Down Bar on increased volume is followed by an Up Bar closing near its own high. The reaction belongs to the pattern.','Po Down Barze na zwiększonym wolumenie następuje Up Bar z zamknięciem przy własnym maksimum. Reakcja jest częścią formacji.'],chart([...down,[96,98,83,85,240],[86,94,84,93,170]],{highlight:[3,4]})],
  ['4. Shakeout','shakeout',['Shakeout','Shakeout'],['A dip below support is rejected and the wide bar closes in its upper third. The body can be either colour.','Zejście pod wsparcie zostaje odrzucone, a szeroki bar zamyka się w górnej jednej trzeciej. Korpus może mieć dowolny kolor.'],chart([...base,[100,104,82,102,240]],{levels:[[96,['Support','Wsparcie'],c.blue]]})],
  ['5. Two Bar Reversal — the strength side','two-bar-strength',['Two Bar Reversal: strength','Two Bar Reversal: siła'],['The first bar closes low; the second closes at or above the first open. Here the second volume is higher.','Pierwszy bar zamyka się nisko; drugi na poziomie otwarcia pierwszego lub wyżej. Tutaj drugi wolumen jest większy.'],chart([...down,[96,97,83,85,180],[85,99,84,98,200]],{highlight:[3,4],levels:[[96,'O₁',c.blue]]})],
  ['6. No Supply','no-supply',['No Supply','No Supply'],['A Down Bar has lower volume than each of the preceding two bars. A bullish background and a later upward response matter.','Down Bar ma wolumen niższy od każdego z dwóch poprzednich barów. Ważne są wzrostowe tło i późniejsza reakcja w górę.'],chart([...up,[107,109,103,104,90],[104,106,101,103,35]],{volumeRef:90,volumeLabel:'V(t−1)'})],
  ['7. Test of supply','supply-test',['Test of supply','Test podaży'],['Price revisits an earlier demand area on low volume, leaves a lower wick and closes high. The test needs a subsequent response.','Cena wraca w dawny obszar popytu na małym wolumenie, zostawia dolny knot i zamyka się wysoko. Test wymaga późniejszej reakcji.'],chart([[100,102,90,95,240],[95,107,94,106,160],[106,112,104,110,130],[110,111,101,103,85],[103,104,93,102,30]],{levels:[[95,['Earlier demand','Wcześniejszy popyt'],c.blue]]})],
  ['8. End of the Rising Market','end-rising-market',['End of the Rising Market','End of the Rising Market'],['After a rise, a narrow Up Bar closes near mid-range on the highest volume of the move.','Po wzroście wąski Up Bar zamyka się w środku zakresu na najwyższym wolumenie ruchu.'],chart([...up,[108,111,107,109,350]])],
  ['9. Buying Climax','buying-climax',['Buying Climax','Buying Climax'],['A wide bar after a rise has exceptional volume and fails to close at its high; this example closes mid-range.','Szeroki bar po wzroście ma wyjątkowy wolumen i nie zamyka się przy maksimum; tutaj zamknięcie jest w środku.'],chart([...up,[107,131,105,118,350]])],
  ['10. Supply Coming In','supply-coming-in',['Supply Coming In','Supply Coming In'],['An Up Bar leaves an upper wick on increased volume, but its volume is not the highest of the rise.','Up Bar zostawia górny knot na zwiększonym wolumenie, który nie jest jednak najwyższy w ruchu wzrostowym.'],chart([[88,96,86,94,220],[94,102,92,100,95],[100,109,98,107,100],[108,122,106,111,170]])],
  ['11. Trap Upmove','trap-upmove',['Trap Upmove','Trap Upmove'],['Price attempts to rise above a local high, then closes low on increased volume.','Cena próbuje wyjść ponad lokalny szczyt, po czym zamyka się nisko na zwiększonym wolumenie.'],chart([...up,[108,120,103,105,210]],{levels:[[109,['Local high','Lokalny szczyt'],c.blue]]})],
  ['12. No Result From Effort','no-result-effort',['No Result From Effort','No Result From Effort'],['Volume grows while the closing result deteriorates: the upper excursion is not held.','Wolumen rośnie, ale rezultat zamknięcia słabnie: ruch w górę nie zostaje utrzymany.'],chart([...up,[107,119,105,108,240]])],
  ['13. Two Bar Reversal — the weakness side','two-bar-weakness',['Two Bar Reversal: weakness','Two Bar Reversal: słabość'],['The second bar closes at or below the first open, with volume similar to or greater than the first.','Drugi bar zamyka się na poziomie otwarcia pierwszego lub niżej, przy wolumenie podobnym lub większym.'],chart([...up,[107,119,106,118,180],[118,120,104,105,210]],{highlight:[3,4],levels:[[107,'O₁',c.blue]]})],
  ['14. No Demand','no-demand',['No Demand','No Demand'],['An Up Bar has lower volume than each of the prior two bars. In the course, weakness still depends on background and the later response.','Up Bar ma wolumen niższy niż każdy z dwóch poprzednich barów. W kursie słabość nadal zależy od tła i późniejszej reakcji.'],chart([...down,[96,101,95,99,80],[99,102,98,100,30]],{volumeRef:80,volumeLabel:'V(t−1)'})],
  ['15. Upthrust','upthrust',['Upthrust','Upthrust'],['Price tests or breaches a recent high, then closes in the lower third. Volume distinguishes the course variants.','Cena testuje lub przekracza wcześniejszy szczyt, po czym zamyka się w dolnej jednej trzeciej. Wolumen rozróżnia warianty kursowe.'],chart([...base,[101,119,97,100,180]],{levels:[[104,['Recent high','Wcześniejszy szczyt'],c.blue]]})],
]
for(const [section,id,title,caption,scene] of coursePatterns) comp(section,id,title,caption,scene,'paragraph')

