const ratingDocs=['en','pl'].map(lang=>fs.readFileSync(path.join(content,`vsaRating${lang==='en'?'.en':''}.md`),'utf8'))
const ratingRows=ratingDocs.map(md=>[...md.matchAll(/^\| (Spring|Sign of Strength[^|]*|Successful Test|Upthrust|Sign of Weakness[^|]*|No Demand) \|[^|]+\|([^|]+)\|[^\n]+/gm)])
ratingPatterns.forEach(([id,title,scene],i)=>add('vsaRating','The six patterns the engine looks for',`rating-${id}`,title,ratingRows.map(rows=>strip(rows[i][2].trim())),scene,'table'))
add('vsaRating','The background check','rating-background',['Rising, neutral or falling background','Tło wzrostowe, neutralne lub spadkowe'],['The previous close is compared with the prior 30-session average. The neutral band lies between −3% and +3%.','Poprzednie zamknięcie jest porównywane ze średnią wcześniejszych 30 sesji. Neutralny przedział leży między −3% i +3%.'],range(90,110,105,[[97,'−3%: 97',c.down],[100,'MA 30 = 100',c.blue],[103,'+3%: 103',c.up],[105,'C(t−1) = 105',c.gold]],['Compare with earlier data','Porównuj z wcześniejszymi danymi'],{zone:[97,103]}))
add('vsaRating','The background check','rating-climax-filter',['Climax exceptions','Wyjątki dla kulminacji'],['More than four times average volume changes how the engine treats certain extreme bars: an upward climax is bearish, and a downward stopping-volume case is ignored.','Ponad czterokrotny średni wolumen zmienia interpretację niektórych skrajnych barów: kulminacja wzrostowa jest spadkowa, a przypadek zatrzymywania spadku jest pomijany.'],flow([['V > 4 × average','V > 4 × średnia'],['Check direction and context','Sprawdź kierunek i tło'],['Reclassify / ignore','Zmień klasyfikację / pomiń']],['The full conditions are in the adjacent text','Pełne warunki znajdują się w tekście obok']))
add('vsaRating','From patterns to one number','rating-decay',['Signal weights fade with age','Wagi sygnałów maleją z wiekiem'],['A signal retains half its weight after 30 days and one quarter after 60 days.','Po 30 dniach sygnał zachowuje połowę wagi, a po 60 dniach jedną czwartą.'],columns([100,50,25,12.5],[['0 days','0 dni'],['30 days','30 dni'],['60 days','60 dni'],['90 days','90 dni']],{unit:['REMAINING WEIGHT (%)','POZOSTAŁA WAGA (%)']}),'paragraph')
add('vsaRating','From patterns to one number','rating-transform',['Net score → rating','Wynik netto → rating'],['The tanh transformation keeps the rating between 0 and 100. Opposing weights can cancel around neutral 50.','Przekształcenie tanh utrzymuje rating między 0 i 100. Przeciwne wagi mogą się znosić wokół neutralnego 50.'],lines([{label:['Rating','Rating'],values:Array.from({length:41},(_,i)=>50+50*Math.tanh((-4+i*.2)/2))}],{min:0,max:100,levels:[[0,'0'],[50,'50'],[100,'100']],axis:['Net −4','Net +4'],note:'50 + 50 × tanh(net / 2)'}))
add('vsaRating','Where you see it in the app','weekly-confirmation',['Daily and weekly confirmation','Potwierdzenie dzienne i tygodniowe'],['The weekly chip compares directions from the daily and weekly engines; a neutral side produces no confirmation chip.','Znacznik tygodniowy porównuje kierunki silnika dziennego i tygodniowego; strona neutralna nie daje znacznika potwierdzenia.'],flow([['Daily ↑ / weekly ↑','Dzienny ↑ / tydz. ↑'],['Daily ↑ / weekly ↓','Dzienny ↑ / tydz. ↓'],['Either neutral','Jedna strona neutralna']],['Agreement / disagreement / no chip','Zgodność / niezgodność / brak znacznika']))

// Basic VSA definitions, including distinctions that candle colour can obscure.
comp('1. What VSA is','vsa-inputs',['VSA: price, volume and context','VSA: cena, wolumen i kontekst'],['VSA relates the price range and closing position to volume, then checks the preceding context. OHLCV does not identify the traders.','VSA wiąże zakres i położenie zamknięcia z wolumenem, a następnie sprawdza wcześniejsze tło. OHLCV nie identyfikuje uczestników.'],flow([['Range H − L','Zakres H − L'],['Closing position','Położenie close'],['Relative volume','Wolumen względny'],['Earlier context','Wcześniejsze tło']]))
comp('Range (spread)','spread-body',['Spread and body are different','Spread i korpus to różne wielkości'],['Spread is H − L. The body is the distance between O and C; wicks complete the full range.','Spread to H − L. Korpus jest odległością między O i C; knoty dopełniają cały zakres.'],{type:'anatomy',items:[[102,112,96,108],[102,106,100,104]],labels:[['Spread = 16; body = 6','Spread = 16; korpus = 6'],['Spread = 6; body = 2','Spread = 6; korpus = 2']]})
comp('Where the bar closes','close-position',['Close high and close low','Zamknięcie wysoko i nisko'],['Relative close position is (C − L) / (H − L). The examples have identical ranges but different closes.','Względna pozycja zamknięcia to (C − L) / (H − L). Przykłady mają ten sam zakres, lecz różne zamknięcia.'],{type:'anatomy',items:[[100,112,96,110],[108,112,96,98]],labels:[['High close: 0.875','Wysokie close: 0,875'],['Low close: 0.125','Niskie close: 0,125']],note:'(C − L) / (H − L)'})
comp('Up Bar, Down Bar and body colour','up-bar-red-body',['Up Bar with a red body','Up Bar z czerwonym korpusem'],['C = 102 is above the previous close of 100, although it is below the current open of 104.','C = 102 jest ponad poprzednim zamknięciem 100, choć poniżej bieżącego otwarcia 104.'],chart([[98,102,97,100,80],[104,105,101,102,90]],{levels:[[100,['Previous close','Poprzednie close'],c.blue]],note:'102 > 100; 102 < 104'}))
comp('Up Bar, Down Bar and body colour','down-bar-green-body',['Down Bar with a green body','Down Bar z zielonym korpusem'],['C = 100 is below the previous close of 102, although it is above the current open of 98.','C = 100 jest poniżej poprzedniego zamknięcia 102, choć ponad bieżącym otwarciem 98.'],chart([[100,104,99,102,80],[98,101,97,100,90]],{levels:[[102,['Previous close','Poprzednie close'],c.blue]],note:'100 < 102; 100 > 98'}))
comp('Volume','volume-comparison',['Volume is a relative comparison','Wolumen jest porównaniem względnym'],['The last volume is lower than each of the preceding two values. Pink is merely a platform display convention.','Ostatni wolumen jest niższy od każdej z dwóch poprzednich wartości. Różowy to jedynie konwencja prezentacji platformy.'],columns([120,90,35],['t − 2','t − 1','t'],{colors:[c.blue,c.blue,c.purple],note:'35 < 90; 35 < 120'}))
comp('Volume','volume-vs-open-interest',['Volume versus open interest','Wolumen a liczba otwartych kontraktów'],['Traded contracts during a period and contracts still open are different measurements. Shares, contracts and tick counts also use different units.','Kontrakty obrócone w okresie i kontrakty nadal otwarte to różne miary. Akcje, kontrakty i liczba ticków również mają różne jednostki.'],flow([['Volume: traded in interval','Wolumen: obrót w okresie'],['Open interest: still open','Open interest: nadal otwarte']],['Compare the same instrument, feed and interval','Porównuj ten sam instrument, źródło i interwał']))
comp('Effort-result','effort-result-detail',['Effort does not determine direction','Wysiłek nie określa kierunku'],['Large volume can accompany either clear price progress or a rejected move. The close and the context decide the reading.','Duży wolumen może towarzyszyć zarówno postępowi ceny, jak i odrzuconemu ruchowi. Odczyt zależy od zamknięcia i tła.'],chart([[100,114,99,113,200],[113,126,108,110,240]],{highlight:[0,1],labels:[[0,['Progress','Postęp']],[1,['Rejection','Odrzucenie']]]}))
comp('Background — the market backdrop','background-structure',['Background: the preceding structure','Background: wcześniejsza struktura'],['The same local bar must be placed within earlier swings, support or resistance, and prior strength or weakness.','Ten sam lokalny bar trzeba umieścić wśród wcześniejszych fal, wsparcia lub oporu oraz sygnałów siły lub słabości.'],lines([{label:['Higher highs / lows','Wyższe szczyty / dołki'],values:[90,110,100,122,112,130],color:c.up},{label:['Lower highs / lows','Niższe szczyty / dołki'],values:[130,110,120,98,108,90],color:c.down}],{points:true,note:['Read the structure before the local signal','Odczytaj strukturę przed lokalnym sygnałem']}))
comp('The character of volume on waves','bullish-volume-waves',['Bullish volume on waves','Wzrostowy charakter wolumenu na falach'],['The upward impulse carries more volume than the pullback. This describes waves rather than demanding that every bar follows the same rule.','Impuls wzrostowy ma większy wolumen niż korekta. To opis fal, a nie wymóg identycznego zachowania każdej świecy.'],chart([[90,100,88,98,150],[98,111,97,109,180],[109,120,107,118,200],[118,119,112,114,80],[114,115,108,110,55]],{highlight:[],labels:[[1,['Impulse','Impuls']],[4,['Correction','Korekta']]]}))
comp('The character of volume on waves','bearish-volume-waves',['Bearish volume on waves','Spadkowy charakter wolumenu na falach'],['Declining waves carry more volume than rebounds; compare whole segments of the same instrument.','Fale spadkowe mają większy wolumen niż odbicia; porównuj całe odcinki tego samego instrumentu.'],chart([[118,120,107,109,150],[109,111,97,99,180],[99,101,87,90,200],[90,97,89,95,80],[95,102,94,100,55]],{highlight:[],labels:[[1,['Impulse','Impuls']],[4,['Rebound','Odbicie']]]}))
comp('Timeframe','timeframe-context',['Higher timeframe and local trigger','Wyższy interwał i lokalny sygnał'],['The higher interval provides context and the lower one provides detail. Agreement is useful, but a conflict is not resolved by changing charts until one fits.','Wyższy interwał daje kontekst, a niższy szczegóły. Zgodność jest użyteczna, lecz konfliktu nie rozwiązuje dobieranie pasującego wykresu.'],flow([['Higher interval: context','Wyższy interwał: tło'],['Lower interval: location','Niższy interwał: miejsce'],['Local pattern + response','Lokalny sygnał + reakcja']],['Example pair: 1 hour → 5 minutes','Przykładowa para: 1 godzina → 5 minut']))
comp('4. Signal classes and the signal catalogue','signal-classes',['Strength and weakness: three classes','Siła i słabość: trzy klasy'],['The course groups signals by accumulation/distribution, gathering/flooding, and testing. Context can change the class of a particular pattern.','Kurs grupuje sygnały jako akumulację/dystrybucję, zbieranie/zalewanie oraz testowanie. Tło może zmienić klasę konkretnej formacji.'],flow([['Accumulation','Akumulacja'],['Gathering supply','Zbieranie podaży'],['Testing supply','Test podaży'],['Distribution','Dystrybucja'],['Flooding demand','Zalewanie popytu'],['Testing demand','Test popytu']]))
comp('5. The test as a process, not a single candle','test-process',['A test is a sequence','Test jest sekwencją'],['Earlier strength is followed by a rebound, a quiet retest of the area, then an upward response. Without the response the test remains unconfirmed.','Po wcześniejszej sile następuje odbicie, spokojny powrót w obszar i reakcja w górę. Bez reakcji test pozostaje niepotwierdzony.'],chart([[100,102,85,93,250],[93,109,91,107,180],[107,115,105,112,130],[112,113,99,102,65],[102,104,92,101,35],[101,112,100,111,100]],{highlight:[0,4,5],levels:[[93,['Test area','Obszar testu'],c.blue]],labels:[[0,['Strength','Siła']],[4,['Test','Test']],[5,['Response','Reakcja']]]}))
comp('Rising and falling sequences','bullish-sequence',['A bullish three-signal sequence','Wzrostowa sekwencja trzech sygnałów'],['Accumulation, supply gathering and supply testing form an ordered hypothesis. A later response is still required.','Akumulacja, zbieranie podaży i test podaży tworzą uporządkowaną hipotezę. Nadal potrzebna jest późniejsza reakcja.'],flow([['Accumulation','Akumulacja'],['Gathering supply','Zbieranie podaży'],['Testing supply','Test podaży'],['Upward response','Reakcja w górę']]))
comp('Rising and falling sequences','bearish-sequence',['A bearish three-signal sequence','Spadkowa sekwencja trzech sygnałów'],['Distribution, demand flooding and demand testing require a later downward response to support the scenario.','Dystrybucja, zalewanie popytu i test popytu wymagają późniejszej reakcji w dół potwierdzającej scenariusz.'],flow([['Distribution','Dystrybucja'],['Flooding demand','Zalewanie popytu'],['Testing demand','Test popytu'],['Downward response','Reakcja w dół']]))
comp('WFO — the volume reversal formation','wfo-bullish',['Bullish WFO: two lower extremes','Wzrostowe WFO: dwa coraz niższe dołki'],['The second trough is lower in price. V1 exceeds V2, and V2 exceeds every volume between the extrema; this is not a reversal guarantee.','Drugi dołek jest niższy cenowo. V1 przewyższa V2, a V2 każdy wolumen między ekstremami; nie gwarantuje to odwrócenia.'],chart([[102,105,88,94,240],[94,108,93,106,80],[106,111,101,108,65],[108,109,96,100,90],[100,102,84,92,170]],{highlight:[0,4],labels:[[0,'V1 = 240'],[4,'V2 = 170']],levels:[[88,'L₁',c.blue],[84,'L₂ < L₁',c.purple]],note:'240 > 170 > max(80, 65, 90)'}))
comp('WFO — the volume reversal formation','wfo-bearish',['Bearish WFO: two higher extremes','Spadkowe WFO: dwa coraz wyższe szczyty'],['The second peak is higher in price, with the same V1 > V2 > intervening volumes relation.','Drugi szczyt jest wyższy cenowo, przy tej samej relacji V1 > V2 > wolumeny pomiędzy.'],chart([[98,112,95,106,240],[106,107,92,94,80],[94,99,89,92,65],[92,104,91,100,90],[100,116,98,108,170]],{highlight:[0,4],labels:[[0,'V1 = 240'],[4,'V2 = 170']],levels:[[112,'H₁',c.blue],[116,'H₂ > H₁',c.purple]],note:'240 > 170 > max(80, 65, 90)'}))
comp('Corrections','quiet-correction',['Correction on declining volume','Korekta na malejącym wolumenie'],['An opposing move on quieter volume can be a correction in the dominant trend. Rising volume and wide opposing bars weaken that interpretation.','Ruch przeciwny na cichszym wolumenie może być korektą trendu. Rosnący wolumen i szerokie przeciwne bary osłabiają tę interpretację.'],chart([...up,[107,109,102,104,70],[104,105,100,102,45],[102,104,99,101,25]],{highlight:[3,4,5]}))
comp('Corrections','correction-accent',['A correction ending with a sharp accent','Korekta zakończona wyraźnym akcentem'],['The course also describes a sharp rejection on increased volume at the end of a correction; it sets no universal numeric threshold.','Kurs opisuje też ostre odrzucenie na zwiększonym wolumenie na końcu korekty; nie ustala uniwersalnego progu liczbowego.'],chart([...up,[107,109,102,104,70],[104,105,99,101,45],[101,104,89,103,190]]))
comp('Corrections','abc-correction',['ABC correction','Korekta ABC'],['A, B and C label successive corrective legs. The course does not provide one universal automatic swing-detection rule.','A, B i C oznaczają kolejne odcinki korekty. Kurs nie podaje jednej uniwersalnej reguły automatycznego wykrywania fal.'],lines([{label:['Price: impulse then ABC','Cena: impuls, potem ABC'],values:[85,100,92,112,105,130,113,122,108,115]}],{points:true,note:['From the peak: A down → B up → C down','Od szczytu: A w dół → B w górę → C w dół']}))
comp('7. Geometry as a level to watch','retracement-zones',['Retracement zones','Strefy zniesienia'],['For the illustrated rise from 100 to 140, the 50% retracement is 120 and the 61.8% retracement is 115.28. A level alone is not a signal.','Dla pokazanego wzrostu ze 100 do 140 zniesienie 50% to 120, a 61,8% to 115,28. Sam poziom nie jest sygnałem.'],range(100,140,120,[[140,'H = 140'],[120,'50% → 120',c.blue],[115.28,'61.8% → 115.28',c.purple],[100,'L = 100']],['140 − (140 − 100) × ratio','140 − (140 − 100) × współczynnik']))

// Every candle formation named in the complementary-candles section.
const candleSection='Candles and bars as a complement to VSA'
const candles=[
  ['hammer',['Hammer','Młot'],['After a decline: a long lower wick, small body near the high and no large upper wick. Colour alone is not decisive.','Po spadku: długi dolny knot, mały korpus przy maksimum i brak dużego górnego knota. Sam kolor nie rozstrzyga.'],[...down,[93,97,76,96,180]]],
  ['shooting-star',['Shooting star','Spadająca gwiazda'],['After a rise: a long upper wick, small body near the low and no large lower wick.','Po wzroście: długi górny knot, mały korpus przy minimum i brak dużego dolnego knota.'],[...up,[108,128,104,105,180]]],
  ['piercing-line',['Piercing line','Formacja przenikania'],['A falling candle is followed by an upward candle closing above the midpoint of the first body. Location and volume remain necessary context.','Po świecy spadkowej pojawia się wzrostowa, zamknięta ponad środkiem pierwszego korpusu. Miejsce i wolumen pozostają koniecznym tłem.'],[...down,[96,98,82,84,150],[81,94,80,93,180]]],
  ['morning-star',['Morning star','Gwiazda poranna'],['A large down body, a small middle body and a recovery into the first body illustrate the three-candle shape.','Duży korpus spadkowy, mały korpus środkowy i powrót w pierwszy korpus ilustrują układ trzech świec.'],[...down,[96,98,82,84,160],[81,83,78,80,70],[83,96,82,95,180]]],
  ['evening-star',['Evening star','Gwiazda wieczorna'],['A large up body, a small middle body and a decline into the first body. The compendium does not supply a separate complete trading strategy for this shape.','Duży korpus wzrostowy, mały środkowy i spadek w pierwszy korpus. Kompendium nie podaje osobnej pełnej strategii dla tego kształtu.'],[...up,[107,122,106,120,160],[123,126,121,124,70],[120,121,108,109,180]]],
  ['dark-cloud',['Dark cloud cover','Zasłona ciemnej chmury'],['A down candle opens above the prior body and closes below its midpoint. It needs the surrounding VSA context.','Świeca spadkowa otwiera się ponad poprzednim korpusem i zamyka poniżej jego środka. Wymaga kontekstu VSA.'],[...up,[107,122,106,120,150],[124,125,110,111,180]]],
  ['bearish-engulfing',['Bearish engulfing','Objęcie bessy'],['The second, falling body covers the previous rising body. This compares bodies, not necessarily the full wick-to-wick ranges.','Drugi, spadkowy korpus obejmuje poprzedni wzrostowy. Porównuje się korpusy, niekoniecznie pełne zakresy z knotami.'],[...up,[107,119,104,116,140],[119,121,102,103,180]]],
  ['inside-up',['Inside Bar: upward breakout','Inside Bar: wybicie w górę'],['The second range lies wholly inside the first; a third bar breaks above the first high. Body colour does not define the pattern.','Zakres drugiego bara mieści się w pierwszym; trzeci wybija ponad maksimum pierwszego. Kolor korpusu nie definiuje układu.'],[[100,115,90,110,160],[108,112,97,101,70],[102,120,100,118,180]]],
  ['inside-down',['Inside Bar: downward breakout','Inside Bar: wybicie w dół'],['The second range lies wholly inside the first; a third bar breaks below the first low.','Zakres drugiego bara mieści się w pierwszym; trzeci wybija poniżej minimum pierwszego.'],[[110,115,90,100,160],[101,112,97,108,70],[106,108,85,87,180]]],
]
for(const [id,title,caption,bars] of candles) comp(candleSection,id,title,caption,chart(bars,{highlight:bars.length>5?[3,4,5]:[bars.length-2,bars.length-1]}))

// Decision, risk and validation definitions from the compendium and appendix.
comp('8. The decision process from observation to trade','direction-vs-plan',['Direction is not a complete trade plan','Kierunek to nie pełny plan transakcji'],['A directional opinion becomes a scenario only when the trigger, invalidation and management rules are specified.','Opinia o kierunku staje się scenariuszem dopiero po określeniu warunku wejścia, unieważnienia i prowadzenia pozycji.'],flow([['Background','Tło'],['Hypothesis','Hipoteza'],['Trigger + invalidation','Sygnał + unieważnienie'],['Size + management','Wielkość + prowadzenie']]))
comp('Scenario no. 5 as an example of the process, not a universal template','scenario-five',['Scenario 5: alternative locations','Scenariusz 5: alternatywne miejsca'],['An ABC end, a WFO or a geometric level are alternative ways to identify the important area, followed by further conditions.','Koniec ABC, WFO lub poziom geometryczny to alternatywne sposoby znalezienia ważnego miejsca, po których następują dalsze warunki.'],flow([['ABC OR WFO OR geometry','ABC LUB WFO LUB geometria'],['Corrective approach','Podejście korekcyjne'],['Candle + VSA confirmation','Świeca + potwierdzenie VSA'],['Potential ≥ 3R','Potencjał ≥ 3R']]))
comp('The trade plan as a card filled in before entry','trade-plan',['The trade plan before entry','Plan transakcji przed wejściem'],['Record evidence and invalidation before seeing the outcome, so the plan can be audited afterwards.','Zapisz przesłanki i unieważnienie przed poznaniem wyniku, aby później można było sprawdzić plan.'],flow([['Instrument + data','Instrument + dane'],['Context + hypothesis','Tło + hipoteza'],['Trigger + stop','Wejście + stop'],['Risk + size + costs','Ryzyko + ilość + koszty'],['Target + management','Cel + prowadzenie'],['Uncertainty + result','Niepewność + wynik']]))
comp('Stop loss and position size','stop-loss',['Stop loss and invalidation','Stop loss i unieważnienie'],['A planned stop lies beyond the level that invalidates the scenario. A gap can produce a worse execution price.','Planowany stop leży za poziomem unieważniającym scenariusz. Luka może spowodować gorszą cenę wykonania.'],range(90,110,100,[[100,['Entry = 100','Wejście = 100'],c.blue],[95,'SL = 95',c.down],[92,['Gap fill = 92','Wykonanie po luce = 92'],c.gold]],['Planned distance = 5; gap loss can exceed 5','Planowana odległość = 5; luka może zwiększyć stratę']))
comp('Stop loss and position size','position-size',['Position size: an arithmetic example','Wielkość pozycji: przykład obliczenia'],['The article example budgets 100, risks 5 plus 0.20 costs per unit, then rounds 19.2307 down to 19.23 for a 0.01 quantity step. This is an illustration, not a risk recommendation.','Przykład z artykułu zakłada budżet 100, ryzyko 5 plus 0,20 kosztu na jednostkę i zaokrąglenie 19,2307 w dół do 19,23 przy kroku 0,01. To ilustracja, nie zalecenie ryzyka.'],flow([['10,000 × 1% = 100','10 000 × 1% = 100'],['100 − 95 + 0.20 = 5.20','100 − 95 + 0,20 = 5,20'],['100 / 5.20 = 19.2307','100 / 5,20 = 19,2307'],['Round down: 19.23','Zaokrąglij w dół: 19,23']]))
comp('Reward to risk','reward-risk',['R and reward-to-risk','R i relacja zysku do ryzyka'],['With entry 100, stop 95 and target 115, the initial risk is 5 and the planned reward is 15, or 3R. The ratio does not establish a profitable strategy.','Przy wejściu 100, stopie 95 i celu 115 początkowe ryzyko to 5, a planowany zysk 15, czyli 3R. Sama relacja nie dowodzi rentowności strategii.'],range(95,115,100,[[115,['Target: +3R','Cel: +3R'],c.up],[100,['Entry: 0R','Wejście: 0R'],c.blue],[95,['Stop: −1R','Stop: −1R'],c.down]],'R = 100 − 95 = 5',{note:'15 / 5 = 3 : 1'}))
comp('Reward to risk','breakeven-rate',['Break-even under a simplified 3R model','Próg rentowności w uproszczonym modelu 3R'],['One +3R win balances three −1R losses before costs: 25% winners. Different exits and costs change this arithmetic.','Jedna wygrana +3R równoważy trzy straty −1R przed kosztami: 25% wygranych. Inne wyjścia i koszty zmieniają to obliczenie.'],flow([['+3R','+3R'],['−1R','−1R'],['−1R','−1R'],['−1R','−1R']],['Total 0R before costs; not an observed win rate','Razem 0R przed kosztami; to nie zmierzona skuteczność']))
comp('Costs and macro','trading-costs',['Gross result and trading costs','Wynik brutto i koszty transakcji'],['Spread, commission, financing and slippage reduce the net result; tight stops can make these costs proportionally important.','Spread, prowizja, finansowanie i poślizg obniżają wynik netto; przy bliskich stopach ich udział może być duży.'],flow([['Gross result','Wynik brutto'],['Spread + commission','Spread + prowizja'],['Financing + slippage','Finansowanie + poślizg'],['Net result','Wynik netto']],['Subtract costs; do not assume identical costs for every instrument','Odejmij koszty; nie zakładaj takich samych kosztów każdego instrumentu']))
comp('Costs and macro','macro-reactions',['Price reactions to new information','Reakcje ceny na nową informację'],['The course distinguishes continuation, reversal, an initial contrary move and a delayed or unclear reaction. Good news does not guarantee a price rise.','Kurs rozróżnia kontynuację, odwrócenie, początkowy ruch przeciwny i reakcję opóźnioną lub niejasną. Dobra wiadomość nie gwarantuje wzrostu.'],lines([{label:['Continuation','Kontynuacja'],values:[100,100,100,105,110,115]},{label:['Reversal','Odwrócenie'],values:[100,100,100,110,103,97]},{label:['Contrary first','Najpierw przeciwnie'],values:[100,100,100,94,103,112]},{label:['Delayed','Opóźniona'],values:[100,100,100,100,101,106]}],{axis:[['Before release','Przed publikacją'],['After release','Po publikacji']]}))
comp('10. Formalising the method in code and its limits','formalisation',['Observation, formalisation and evidence','Obserwacja, formalizacja i dowód'],['A measurable feature, a chosen threshold and an observed result are separate things. Unspecified course parameters must be disclosed.','Mierzalna cecha, wybrany próg i zmierzony rezultat to odrębne rzeczy. Parametry nieustalone przez kurs trzeba ujawnić.'],flow([['OHLCV features','Cechy OHLCV'],['Explicit thresholds','Jawne progi'],['Pattern candidates','Kandydaci formacji'],['Later validation','Późniejsza weryfikacja']]))
comp('11. What the sources say, and what they do not prove','observation-vs-intent',['Observation versus participant intent','Obserwacja a intencje uczestników'],['Heavy trading with little price progress is observable. The identity and intention of a specific buyer cannot be read from that bar alone.','Duży obrót przy małym postępie ceny jest obserwowalny. Tożsamości i zamiarów konkretnego kupującego nie da się odczytać z samego bara.'],flow([['Observed: high volume','Obserwacja: duży wolumen'],['Observed: small progress','Obserwacja: mały postęp'],['Hypothesis: absorption','Hipoteza: absorpcja']],['A hypothesis about accumulation is not participant identification','Hipoteza akumulacji nie jest identyfikacją uczestników']))
comp('A.1. What is actually calculated','candidate-definition',['Candidate does not mean confirmation','Kandydat nie oznacza potwierdzenia'],['A candidate meets defined pattern conditions. Later confirmation is a separate event, and overlapping names are not independent votes.','Kandydat spełnia zdefiniowane warunki formacji. Późniejsze potwierdzenie to osobne zdarzenie, a nakładające się nazwy nie są niezależnymi głosami.'],flow([['Bar closes','Bar się zamyka'],['Conditions match','Warunki są spełnione'],['Candidate recorded','Zapisano kandydata'],['Wait for response','Oczekiwanie na reakcję']]))
comp('A.2. Running it','ohlcv-data',['OHLCV and valid input data','OHLCV i poprawne dane wejściowe'],['High and Low enclose Open and Close; volume is non-negative. Use ordered timestamps, one instrument and one interval, and exclude unfinished bars.','High i Low obejmują Open i Close; wolumen jest nieujemny. Używaj kolejnych znaczników czasu, jednego instrumentu i interwału, pomijając niedokończone bary.'],{type:'anatomy',items:[[100,112,96,108]],labels:[['O = 100, H = 112, L = 96, C = 108','O = 100, H = 112, L = 96, C = 108']],note:['Volume and timestamp accompany every bar','Wolumen i czas towarzyszą każdemu barowi']} )
comp('A.3. How to read the output','candidate-confirmation-execution',['Candidate → confirmation → execution','Kandydat → potwierdzenie → wykonanie'],['The candidate is known at its close; confirmation happens later; the model executes at the earliest on the next bar open after confirmation.','Kandydat jest znany po zamknięciu; potwierdzenie następuje później; model wykonuje wejście najwcześniej na otwarciu kolejnego bara po potwierdzeniu.'],flow([['t: candidate closes','t: zamknięcie kandydata'],['t + 1: confirmation','t + 1: potwierdzenie'],['t + 2: earliest open','t + 2: najwcześniejsze otwarcie']]))
comp('A.3. How to read the output','intrabar-ambiguity',['One candle does not reveal the path','Jedna świeca nie ujawnia kolejności ruchu'],['If the stop and target are both inside one bar, OHLC alone does not reveal which came first. The model uses a stop-first assumption.','Jeżeli stop i cel leżą wewnątrz jednego bara, samo OHLC nie ujawnia kolejności. Model zakłada wykonanie stopu jako pierwszego.'],{type:'anatomy',items:[[100,112,96,108]],labels:[['SL 98 and target 110 both lie inside H–L','SL 98 i cel 110 leżą wewnątrz H–L']],note:['Execution order is a model assumption','Kolejność wykonania jest założeniem modelu']})
comp('A.4. Risk and units','contract-units',['Price distance is not the whole risk','Odległość ceny to nie całe ryzyko'],['Point value, position quantity, costs and currency conversion determine money at risk. One instrument unit is not automatically one futures contract or FX lot.','Wartość punktu, ilość, koszty i przeliczenie walut określają ryzyko pieniężne. Jednostka instrumentu nie oznacza automatycznie kontraktu futures lub lota FX.'],flow([['Price distance','Odległość ceny'],['Point / tick value','Wartość punktu / ticka'],['Quantity + costs','Ilość + koszty'],['Account currency','Waluta rachunku']]))
comp('A.4. Risk and units','drawdown',['Drawdown from an equity peak','Obsunięcie od szczytu kapitału'],['Drawdown measures a decline from an earlier equity peak. In this model it is measured at candle closes, not at every intrabar price.','Obsunięcie mierzy spadek od wcześniejszego szczytu kapitału. W tym modelu jest mierzone na zamknięciach, nie przy każdej cenie wewnątrz świecy.'],lines([{label:['Equity','Kapitał'],values:[100,104,110,106,101,99,103,108]}],{levels:[[110,['Previous peak','Wcześniejszy szczyt']]],points:true,note:['Peak 110 → trough 99: 10% drawdown','Szczyt 110 → dołek 99: obsunięcie 10%']}))
comp('A.5. What the program\'s tests prove','out-of-sample',['Out-of-sample validation','Weryfikacja poza próbą uczącą'],['Fix the rules before checking the later period. A correct calculation is not evidence of a profitable strategy.','Ustal reguły przed sprawdzeniem późniejszego okresu. Poprawne obliczenie nie dowodzi rentowności strategii.'],flow([['Earlier data: develop','Wcześniejsze dane: opracuj'],['Freeze the settings','Zamroź ustawienia'],['Later data: validate','Późniejsze dane: sprawdź'],['Include costs + baseline','Uwzględnij koszty + bazę']]))
comp('A.5. What the program\'s tests prove','lookahead-bias',['Causality: future bars cannot rewrite the past','Przyczynowość: przyszłe bary nie zmieniają przeszłości'],['Adding later bars must not change earlier features or analytical events. A swing requiring later confirmation becomes known only after that delay.','Dodanie późniejszych barów nie może zmieniać wcześniejszych cech ani zdarzeń analitycznych. Ekstremum wymagające późniejszego potwierdzenia jest znane dopiero po opóźnieniu.'],flow([['Data through t','Dane do t'],['Record result at t','Zapisz wynik w t'],['Append later data','Dodaj późniejsze dane'],['Earlier result unchanged','Wcześniejszy wynik bez zmian']]))
